                "text": "Is A-tempo vroeg in de race al ongewoon zwaar, kies een rustiger ritme op basis van je werkelijke inspanning; B en C zijn mogelijke uitkomsten, geen opdracht om alsnog een gegarandeerde tijd te halen. Geen agressieve positive split plannen en geen sprint om tijdverlies in te halen. Run-walk is uitsluitend een noodalternatief bij normaal uitputtingsverval zonder medische stopreden, geen basisraceplan. Bij een medische stopreden geldt §2."
